'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var isObject = require( '@stdlib/assert/is-object' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var LineChart = require( './../lib' );


// MAIN //

bench( format( '%s::instantiation', pkg ), function benchmark( b ) {
	var v;
	var i;
	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v = new LineChart();
		if ( !( v instanceof LineChart ) ) {
			b.fail( 'should return an instance' );
		}
	}
	b.toc();
	if ( !( v instanceof LineChart ) ) {
		b.fail( 'should return an instance' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::instantiation,no_new', pkg ), function benchmark( b ) {
	var ctor;
	var v;
	var i;

	ctor = LineChart;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v = ctor();
		if ( !( v instanceof LineChart ) ) {
			b.fail( 'should return an instance' );
		}
	}
	b.toc();
	if ( !( v instanceof LineChart ) ) {
		b.fail( 'should return an instance' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::instantiation,options', pkg ), function benchmark( b ) {
	var opts;
	var v;
	var i;

	opts = {
		'colors': [ 'red', 'blue' ],
		'legend': true,
		'lineOpacity': [ 1.0, 0.5 ],
		'lineStyle': [ '-', '--' ],
		'lineSymbol': [ 'stroke', 'circle' ],
		'lineWidth': [ 2, 4 ]
	};
	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v = new LineChart( opts );
		if ( !( v instanceof LineChart ) ) {
			b.fail( 'should return an instance' );
		}
	}
	b.toc();
	if ( !( v instanceof LineChart ) ) {
		b.fail( 'should return an instance' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::instantiation,x,y', pkg ), function benchmark( b ) {
	var x;
	var y;
	var v;
	var i;

	x = [ 1, 2, 3 ];
	y = [ 4, 5, 6 ];

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v = new LineChart( x, y );
		if ( !( v instanceof LineChart ) ) {
			b.fail( 'should return an instance' );
		}
	}
	b.toc();
	if ( !( v instanceof LineChart ) ) {
		b.fail( 'should return an instance' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::set,get:colors', pkg ), function benchmark( b ) {
	var values;
	var chart;
	var v;
	var i;

	chart = new LineChart();
	values = [
		[ 'red' ],
		[ 'blue' ]
	];

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		chart.colors = values[ i%values.length ];
		v = chart.colors;
		if ( typeof v !== 'object' ) {
			b.fail( 'should return an array' );
		}
	}
	b.toc();
	if ( typeof v !== 'object' ) {
		b.fail( 'should return an array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::set,get:legend', pkg ), function benchmark( b ) {
	var values;
	var chart;
	var v;
	var i;

	chart = new LineChart();
	values = [
		true,
		false
	];

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		chart.legend = values[ i%values.length ];
		v = chart.legend;
		if ( typeof v !== 'boolean' ) {
			b.fail( 'should return a boolean' );
		}
	}
	b.toc();
	if ( typeof v !== 'boolean' ) {
		b.fail( 'should return a boolean' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

